  case 0:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: No PID set -> Using default PION hypothesis";
    pid_hyp = 211;
    break;
  case 11:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Using ELECTRON hypothesis";
    pid_hyp = -11;
    break;
  case 13:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Using MUON hypothesis";
    pid_hyp = -13;
    break;
  case 211:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Using PION hypothesis";
    pid_hyp = 211;
    break;
  case 321:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Using KAON hypothesis";
    pid_hyp = 321;
    break;
  case 2212:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Using PROTON hypothesis";
    pid_hyp = 2212;
    break;
  default:
    LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Not recognised PID set -> Using default PION hypothesis";
    pid_hyp = 211;
    break;
  }
  return pid_hyp;
}

